    equipment_id VARCHAR(64) NOT NULL,
    install_reading_id VARCHAR(64) NOT NULL,
    install_sampled_at TIMESTAMP WITH TIME ZONE NOT NULL,
    install_cumulative_minutes BIGINT NOT NULL,
    remove_reading_id VARCHAR(64) NULL,
    remove_sampled_at TIMESTAMP WITH TIME ZONE NULL,
    remove_cumulative_minutes BIGINT NULL,
    open_component_id VARCHAR(64) NULL,
    install_operator VARCHAR(64) NOT NULL,
    remove_operator VARCHAR(64) NULL,
    install_request_id VARCHAR(128) NOT NULL,
    remove_request_id VARCHAR(128) NULL,
    installed_at TIMESTAMP WITH TIME ZONE NOT NULL,
    removed_at TIMESTAMP WITH TIME ZONE NULL,
    CONSTRAINT uq_component_install_open UNIQUE (open_component_id)
);
CREATE INDEX IF NOT EXISTS idx_component_install_component ON component_install (component_id, install_id);
CREATE INDEX IF NOT EXISTS idx_component_install_reading ON component_install (equipment_id, install_reading_id);
CREATE INDEX IF NOT EXISTS idx_component_install_remove_reading ON component_install (equipment_id, remove_reading_id);
COMMENT ON TABLE component_install IS '部件装拆账：区间左闭右开；open_component_id 未拆时等于部件编号（唯一），拆卸后置 NULL';
COMMENT ON COLUMN component_install.install_id IS '装拆记录自增主键';
COMMENT ON COLUMN component_install.component_id IS '部件合成编号';
COMMENT ON COLUMN component_install.equipment_id IS '安装所在设备标识';
COMMENT ON COLUMN component_install.install_reading_id IS '安装引用的设备读数标识（引用后该读数禁止修订）';
COMMENT ON COLUMN component_install.install_sampled_at IS '安装读数的 UTC 采样时刻（快照，区间起点，含）';
COMMENT ON COLUMN component_install.install_cumulative_minutes IS '安装时设备累计工时快照（分钟）';
COMMENT ON COLUMN component_install.remove_reading_id IS '拆卸引用的设备读数标识；NULL 表示尚未拆卸';
COMMENT ON COLUMN component_install.remove_sampled_at IS '拆卸读数的 UTC 采样时刻（快照，区间终点，不含）；NULL 表示尚未拆卸';
COMMENT ON COLUMN component_install.remove_cumulative_minutes IS '拆卸时设备累计工时快照（分钟），不得小于安装累计；NULL 表示尚未拆卸';
COMMENT ON COLUMN component_install.open_component_id IS '未拆卸时等于部件编号（唯一约束保证同部件同一时刻仅装一台），拆卸后置 NULL';
COMMENT ON COLUMN component_install.install_operator IS '安装操作者';
COMMENT ON COLUMN component_install.remove_operator IS '拆卸操作者；NULL 表示尚未拆卸';
COMMENT ON COLUMN component_install.install_request_id IS '安装请求的 requestId';
COMMENT ON COLUMN component_install.remove_request_id IS '拆卸请求的 requestId；NULL 表示尚未拆卸';
COMMENT ON COLUMN component_install.installed_at IS '安装登记时刻（UTC）';
COMMENT ON COLUMN component_install.removed_at IS '拆卸登记时刻（UTC）；NULL 表示尚未拆卸';
