        assert r1.getResponse().getStatus() == 409;
        assert r1.getResponse().getContentAsString().contains("COMPONENT_NOT_INSTALLED");

        // 装在 160（r2），拆在 100（r1）：拆卸累计小于安装累计 → 422
        install("C1", "ins-1", 1, "E1", "r2");
